function addOperation(action,target,detail,user='当前预览用户'){
  operationLog.unshift({time:new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}),user,action,target,detail});
  storage.write('ops-operation-log-v1',operationLog);
}
function sparkline(values,color='#4f75f3'){
  const max=Math.max(...values,1),min=Math.min(...values),range=max-min||1;
  const points=values.map((v,i)=>`${8+i*(104/(values.length-1))},${35-(v-min)/range*25}`).join(' ');
  return `<svg class="sparkline" viewBox="0 0 120 42" role="img" aria-label="近7天趋势"><path d="M8 35H112" stroke="rgba(121,134,158,.18)"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}
