function business(){
  const tabs=[['active','正在进行'],['upcoming','即将开始'],['ended','历史结果'],['all','全部活动']];let list=state.activityView==='all'?incentiveActivities:incentiveActivities.filter(x=>x.phase===state.activityView);
  const card=a=>`<article class="activity-card ${a.phase==='upcoming'||a.status.includes('结束')?'focus':''}"><div class="activity-title"><h3>${a.name}</h3>${chip(a.status,a.phase==='upcoming'?'yellow':a.status.includes('结束')||a.status.includes('停止')?'red':'')}</div><div class="activity-meta">活动时间：${a.start}—${a.end}</div><div class="activity-metrics"><div><span>当前有效订单</span><b>${a.orders}</b></div><div><span>下一目标</span><b>${a.target}</b></div><div><span>激励标准</span><b>${a.bonus}</b></div></div>${a.phase==='upcoming'?`<div class="upcoming-policy"><span>活动要求</span><strong>${a.requirement}</strong></div>`:`<div class="activity-daily"><div><span>近7天有效订单</span><strong>${(activityDaily[a.id]||[0]).reduce((n,v)=>n+v,0)} 单</strong></div>${sparkline(activityDaily[a.id]||[0,0,0,0,0,0,0],'#e6aa2d')}</div><div class="context-line"><span>门槛进度</span><strong style="margin-left:auto">${Math.round(a.orders/a.target*100)}% · 距下一档 ${Math.max(0,a.target-a.orders)} 单</strong></div><div class="progress"><span style="width:${Math.min(100,a.orders/a.target*100)}%"></span></div>`}<div class="activity-card-actions"><button class="detail-btn" data-action="activity-detail" data-id="${a.id}">查看要求与数据</button>${a.phase==='active'?`<button class="stop-btn" data-action="stop-activity" data-id="${a.id}">停止并结算</button>`:''}</div></article>`;
  const endedRows=incentiveActivities.filter(x=>x.phase==='ended').map(a=>[a.name,`${a.start}—${a.end}`,a.orders,a.bonus,a.accounts,a.notes,`<button class="detail-btn" data-action="activity-detail" data-id="${a.id}">查看总结</button>`]);let content;
  if(state.activityView==='ended')content=`<div class="card history-card"><div class="card-head"><div><h3>已结束活动汇总</h3><p>包含自然结束与人工停止，均保留停止时订单和门槛比例</p></div></div>${table(['活动名称','活动时间','停止时订单','预估激励','启用账号','发布笔记','活动总结'],endedRows)}</div>`;
  else if(state.activityView==='all')content=`<div class="activity-list">${list.filter(x=>x.phase!=='ended').map(card).join('')}</div><div class="card history-card"><div class="card-head"><div><h3>已结束活动</h3><p>历史结果单独归档</p></div></div>${table(['活动名称','活动时间','停止时订单','预估激励','启用账号','发布笔记','活动总结'],endedRows)}</div>`;
  else content=`<div class="activity-list">${list.map(card).join('')}</div>`;
  return `${pageLead('激励活动中心','跟踪每日订单、门槛进度和最终结算；外部门槛提前达成时可人工停止','<button class="primary" data-action="add">＋ 新增激励活动</button>')}<div class="business-alerts"><div class="business-alert"><span>明天开始</span><strong>三福秋季上新</strong><small>09/24—10/10 · 最高 ¥2.5/单</small></div><div class="business-alert green"><span>正在冲刺</span><strong>名创距下一档 108 单</strong><small>当前 392 单 · 09/30 结束</small></div><div class="business-alert red"><span>外部门槛提醒</span><strong>可随时人工停止活动</strong><small>停止时必须录入订单与门槛比例</small></div></div><div class="view-tabs activity-tabs">${tabs.map(([k,v])=>`<button class="view-tab ${state.activityView===k?'active':''}" data-action="activity-view" data-filter="${k}">${v}</button>`).join('')}</div>${content}`;
}
function stopActivityDrawer(id){
  const a=incentiveActivities.find(x=>x.id===id),ratio=Math.round(a.orders/a.target*100);
  openDrawer(`停止激励 · ${a.name}`,`<form id="stop-activity-form" class="drawer-form" data-id="${a.id}"><div class="danger-note"><strong>停止后将转入历史结果</strong><span>请以停止时的平台数据为准，确认后仍可在飞书底表中更正。</span></div><label>停止时有效订单<input name="orders" type="number" min="0" value="${a.orders}" required /></label><label>已达到门槛比例<input name="ratio" type="number" min="0" max="999" value="${ratio}" required /><span class="field-suffix">%</span></label><label>停止原因<select name="reason"><option>外部总量已先达到活动上限</option><option>平台提前结束活动</option><option>业务主动停止</option><option>数据异常，暂停统计</option></select></label><label>结算备注<textarea name="note" rows="4" placeholder="补充停止时间、确认人或特殊口径"></textarea></label><button class="danger-button" type="submit">确认停止并保存结果</button></form>`);
}
function activityDetail(id){const a=incentiveActivities.find(x=>x.id===id);openDrawer(a.name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>活动时间</span><b>${a.start}—${a.end}</b></div><div><span>有效订单</span><b>${a.orders}</b></div><div><span>激励</span><b>${a.bonus}</b></div></div></div><div class="drawer-section"><h3>活动要求</h3><p>${a.requirement}</p></div><div class="drawer-section"><h3>近7天订单</h3><div class="drawer-trend">${sparkline(activityDaily[a.id]||[0,0,0,0,0,0,0],'#e6aa2d')}<strong>${(activityDaily[a.id]||[0]).reduce((n,v)=>n+v,0)} 单</strong></div></div><div class="drawer-section"><h3>${a.phase==='ended'?'活动结果汇总':'关联数据'}</h3>${table(['指标','数据'],[['启用账号',`${a.accounts} 个`],['发布笔记',`${a.notes} 篇`],['有效订单',`${a.orders} 单`],['预估激励',a.bonus]])}</div>${a.phase==='active'?`<button class="danger-button secondary-danger" data-action="stop-activity" data-id="${a.id}">停止并结算此活动</button>`:''}`)}

function secrets(){
  const groups=['全部','A组','B组','C组'],platforms=['全部','淘宝闪购','美团'];let rows=secretRows;if(state.secretGroup!=='全部')rows=rows.filter(x=>x.group===state.secretGroup);if(state.secretPlatform!=='全部')rows=rows.filter(x=>x.platform===state.secretPlatform);if(state.secretSearch)rows=rows.filter(x=>[x.word,x.biz,x.owner].some(v=>v.includes(state.secretSearch)));const owners={全部:'全部负责人',A组:'胡心玥',B组:'高宇芸',C组:'曾涛'};
  const trs=rows.map(x=>{const meta=secretMeta[x.word]||{tags:[],note:''},trend=secretTrend[x.word]||[0,0,0,0,0,0,0],total=trend.reduce((n,v)=>n+v,0);return [`<button class="row-link secret-word" data-action="secret-detail" data-word="${x.word}">${x.word}</button><small>${meta.note}</small>`,x.platform,x.biz,x.group,x.owner,`<div class="tag-list">${meta.tags.map(t=>chip(t,t==='临期'||t==='停用'||t==='待续期'?'red':'blue')).join('')}</div>`,`<div class="secret-trend">${sparkline(trend,x.days<0?'#d95b62':'#4f75f3')}<b>近7天 ${total} 单</b></div>`,x.expiry,x.days<0?chip(`已到期 ${Math.abs(x.days)} 天`,'red'):x.days<=3?chip(x.days===0?'今天到期':`${x.days}天后到期`,'red'):chip('有效')];});
  return `${pageLead('业务密令中心','除了有效期和归属，也要看到密令近期是否真正产生订单','<button class="primary" data-action="add">＋ 新增密令</button>')}<div class="renewal-automation"><div><strong>到期前 3 天自动创建续期任务</strong><span>组别联动负责人；测试标签用于追踪密令参与了哪些业务测试。</span></div>${chip('规则已启用','green')}</div><div class="kpi-grid">${kpi('有效密令','18','当前仍在有效期内','密')}${kpi('近7天密令订单','225','按推广位名称匹配汇总','单')}${kpi('3天内到期','3','已自动生成续期任务','期',null,'risk')}${kpi('参与测试','2','可回溯测试结果','试',null,'new')}</div><div class="card"><div class="secret-filters"><div><label>负责组</label><div class="group-tabs">${groups.map(g=>`<button class="filter-btn ${state.secretGroup===g?'active':''}" data-action="secret-group" data-group="${g}">${g}</button>`).join('')}</div></div><div><label>所属平台</label><div class="group-tabs">${platforms.map(p=>`<button class="filter-btn ${state.secretPlatform===p?'active':''}" data-action="secret-platform" data-platform="${p}">${p}</button>`).join('')}</div></div><div class="linked-owner"><label>联动负责人</label><strong>${owners[state.secretGroup]}</strong><span>组别改变时自动联动</span></div></div><div class="card-head secret-list-head"><div><h3>密令表现与清单</h3><p>${state.secretGroup} · ${state.secretPlatform} · 共 ${rows.length} 条</p></div><input class="search secret-search" data-action="secret-search" value="${state.secretSearch}" placeholder="搜索密令词、业务或负责人" /></div>${table(['密令词与备注','平台','所属业务','负责组','负责人','标签','近期出单趋势','截止日期','到期状态'],trs,'secret-performance-table')}</div>`;
}
function secretDetail(word){const x=secretRows.find(row=>row.word===word),meta=secretMeta[word],trend=secretTrend[word];openDrawer(`密令 · ${word}`,`<div class="drawer-section"><div class="drawer-kpis"><div><span>平台</span><b>${x.platform}</b></div><div><span>所属业务</span><b>${x.biz}</b></div><div><span>负责人</span><b>${x.owner}</b></div></div></div><div class="drawer-section"><h3>近7天出单趋势</h3><div class="drawer-trend">${sparkline(trend)}<strong>${trend.reduce((n,v)=>n+v,0)} 单</strong></div><p>正式接入后按“推广位名称包含密令词”匹配订单，并保留无法匹配的数据清单。</p></div><div class="drawer-section"><h3>标签与备注</h3><div class="tag-list">${meta.tags.map(t=>chip(t,'blue')).join('')}</div><p>${meta.note}</p></div>`)}

function logs(){
  const tabs=`<div class="view-tabs log-tabs"><button class="view-tab ${state.logTab==='runtime'?'active':''}" data-action="log-tab" data-tab="runtime">运行日志</button><button class="view-tab ${state.logTab==='operation'?'active':''}" data-action="log-tab" data-tab="operation">操作日志</button></div>`;
  if(state.logTab==='operation')return `${pageLead('日志中心','飞书授权登录后，每一次关键修改都记录人员、时间、对象和变更内容',tabs)}<div class="audit-summary"><div><span>记录原则</span><strong>只记录关键变更，不记录普通浏览</strong></div><div><span>人员身份</span><strong>来自飞书授权账号</strong></div><div><span>保留周期</span><strong>建议永久保留</strong></div></div><div class="notice"><span>当前为结构示例；完成飞书 OAuth 后，操作人将由登录身份自动写入，不能手工选择。</span></div><div class="card"><div class="card-head"><div><h3>最近操作记录</h3><p>出现数据问题时，可按对象和人员回溯</p></div><input class="search" placeholder="搜索人员、对象或操作" /></div>${table(['操作时间','操作人','操作类型','修改对象','变更内容'],operationLog.map(x=>[x.time,`<strong>${x.user}</strong>`,x.action,x.target,x.detail]),'audit-table')}</div>`;
  return `${pageLead('日志中心','运行日志看软件是否正常；操作日志看谁修改了业务数据',tabs)}<div class="card issue-card"><div class="issue-top"><div><span class="chip red">需要处理</span><h3>小红书笔记沉淀没有继续采集群消息</h3></div><button class="primary" data-action="repair">检查并尝试恢复</button></div><div class="issue-grid"><div><span>影响</span><strong>新笔记不会自动写入底表</strong></div><div><span>最后正常时间</span><strong>09-22 18:40</strong></div><div><span>建议</span><strong>先执行健康检查，失败后再通知维护</strong></div></div></div><div class="card"><div class="card-head"><div><h3>最近运行记录</h3><p>只显示可理解的状态和处理方式</p></div></div>${table(['时间','功能','发生了什么','当前状态','你需要做什么'],[['09-23 09:40','小红书笔记沉淀','群消息没有被采集',chip('需要处理','red'),'<button class="detail-btn" data-action="repair">检查恢复</button>'],['09-23 09:35','CPS 数据整理','定时整理完成',chip('正常'),'不用处理'],['09-23 09:30','飞书底表同步','尚未完成授权',chip('等待配置','yellow'),'<button class="detail-btn" data-action="login">配置授权</button>']])}</div>`;
}

const renderers={overview,data:dataView,reports,accounts,business,tasks:tasksView,experiments,employees:employeesView,orders,secrets,tools,logs};
function render(preserveScroll=false){
  const y=window.scrollY;
  document.querySelector('#title').textContent=labels[state.view];
  document.querySelector('#crumb').textContent=labels[state.view];
  document.querySelector('#app').innerHTML=renderers[state.view]();
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));
  const taskBadge=document.querySelector('[data-view="tasks"] b');
  if(taskBadge)taskBadge.textContent=tasks.filter(t=>t.status!=='已完成'&&t.status!=='已取消').length;
  if(state.view==='tasks'){
    const values=document.querySelectorAll('.task-kpis .kpi-value');
    const counts=[tasks.filter(t=>t.status==='进行中').length,tasks.filter(t=>t.status==='未开始').length,tasks.filter(t=>t.alert==='临期').length,tasks.filter(t=>t.alert==='已逾期').length];
    values.forEach((el,i)=>el.textContent=counts[i]);
  }
  window.scrollTo({top:preserveScroll?y:0,behavior:'auto'});
}
function goto(view){if(renderers[view]){state.view=view;render()}}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function openDrawer(title,body){const layer=document.querySelector('#drawer');layer.innerHTML=`<aside class="drawer"><div class="drawer-head"><h2>${title}</h2><button class="drawer-close" data-action="close">×</button></div>${body}</aside>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false')}
function closeDrawer(){const layer=document.querySelector('#drawer');layer.classList.remove('open');layer.setAttribute('aria-hidden','true')}
function accountDetail(i){const a=accountsData[i];openDrawer(a[0],`<div class="drawer-section"><div class="drawer-kpis"><div><span>账号状态</span><b>${a[3]}</b></div><div><span>生命周期</span><b>${a[2]}</b></div><div><span>负责人</span><b>${a[4]}</b></div></div></div><div class="drawer-section"><h3>基础信息</h3>${table(['字段','内容'],[['组别',a[1]],['账号性质','专业号'],['新增 / 启用日期',a[5]],['所属企业','待飞书同步'],['IP 网络','待飞书同步']])}</div>`)}
function placementDetail(name){const r=channelRows.find(x=>x.pos===name);openDrawer(name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>有效订单</span><b>${r.orders}</b></div><div><span>成交金额</span><b>${money(r.gmv)}</b></div><div><span>预估佣金</span><b>${money(r.commission)}</b></div></div></div><div class="drawer-section"><h3>归属关系</h3>${table(['层级','内容'],[['组 / 渠道',r.g],['平台',r.p],['业务',r.biz],['推广位',r.pos]])}</div><div class="drawer-section"><h3>查看逻辑</h3><p>正式接入后，这里继续展示该推广位的每日趋势、订单明细和负责人。</p></div>`)}
function activityDetail(id){const a=incentiveActivities.find(x=>x.id===id);openDrawer(a.name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>活动时间</span><b>${a.start}—${a.end}</b></div><div><span>有效订单</span><b>${a.orders}</b></div><div><span>激励</span><b>${a.bonus}</b></div></div></div><div class="drawer-section"><h3>活动要求</h3><p>${a.requirement}</p></div><div class="drawer-section"><h3>${a.phase==='ended'?'活动结果汇总':'关联数据'}</h3>${table(['指标','数据'],[['启用账号',`${a.accounts} 个`],['发布笔记',`${a.notes} 篇`],['有效订单',`${a.orders} 单`],['预估激励',a.bonus]])}</div>`)}

document.addEventListener('change',e=>{if(e.target.dataset.action==='task-owner'){state.taskOwner=e.target.value==='全部负责人'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='task-status'){const t=tasks[Number(e.target.dataset.index)];t.status=e.target.value;if(t.status==='已完成'){t.alert='已完成';t.progress=100}else if(t.alert==='已完成'){t.alert='正常'}render(true);toast('工作状态已更新；正式版会同步写回飞书')}if(e.target.dataset.action==='data-owner'){state.dataOwner=e.target.value==='全部负责人'?'全部':e.target.value;if(state.dataOwner!=='全部')state.dataGroup=employees.find(x=>x.name===state.dataOwner).group;state.dataSource='';render(true)}if(e.target.dataset.action==='data-platform'){state.dataPlatform=e.target.value==='全部平台'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='data-biz'){state.dataBiz=e.target.value==='全部业务'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='data-search'){state.dataSearch=e.target.value;render(true)}if(e.target.dataset.action==='secret-search'){state.secretSearch=e.target.value;render(true)}});
document.addEventListener('change',e=>{if(e.target.dataset.action==='report-period'){state.reportPeriod=e.target.value}if(e.target.dataset.action==='task-status'){const t=tasks[Number(e.target.dataset.index)];addOperation('更新任务状态',t.name,`状态调整为 ${e.target.value}`)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&['data-search','secret-search'].includes(e.target.dataset.action)){if(e.target.dataset.action==='data-search')state.dataSearch=e.target.value;else state.secretSearch=e.target.value;render(true)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-view].nav-item');if(!el)return;const a=el.dataset.action;if(el.classList.contains('nav-item'))return goto(el.dataset.view);if(a==='goto')return goto(el.dataset.view);if(a==='range'){state.range=el.dataset.range;return render(state.view==='data')}if(a==='data-group'){state.dataGroup=el.dataset.group;state.dataOwner='全部';state.dataSource='';return render(true)}if(a==='toggle-data-trend'){state.dataTrendCollapsed=!state.dataTrendCollapsed;return render(true)}if(a==='employee-data'){state.dataGroup=el.dataset.group;state.dataOwner=el.dataset.name;state.range=el.dataset.range||'30d';state.dataPlatform='全部';state.dataBiz='全部';state.dataSearch='';state.dataSource='employee';return goto('data')}if(a==='employee-accounts'){state.accountGroup=el.dataset.group;return goto('accounts')}if(a==='clear-employee-filter'){state.dataOwner='全部';state.dataGroup='全部';state.dataSource='';return render(true)}if(a==='account-group'){state.accountGroup=el.dataset.group;return render(true)}if(a==='task-filter'){state.taskFilter=el.dataset.filter;return render(true)}if(a==='task-detail'){state.taskExpanded=state.taskExpanded===el.dataset.index?'':el.dataset.index;return render(true)}if(a==='activity-view'){state.activityView=el.dataset.filter;return render(true)}if(a==='secret-group'){state.secretGroup=el.dataset.group;return render(true)}if(a==='secret-platform'){state.secretPlatform=el.dataset.platform;return render(true)}if(a==='employee'){state.employee=state.employee===el.dataset.name?'':el.dataset.name;return render(true)}if(a==='account-detail')return accountDetail(Number(el.dataset.index));if(a==='placement-detail')return placementDetail(el.dataset.pos);if(a==='activity-detail')return activityDetail(el.dataset.id);if(a==='close')return closeDrawer();if(a==='refresh')return toast('当前为结构预览；连接飞书后将刷新真实数据');if(a==='add')return toast('接入飞书后将在对应底表中新建记录');if(a==='import')return toast('订单模块暂不作为当前主线');if(a==='tool-open')return toast('接入工具链接后将直接打开');if(a==='edit-tool')return toast('工具信息会存入“工具与自动化”底表');if(a==='login')return toast('需要先配置飞书自建应用的 OAuth 授权信息');if(a==='repair')return toast('已模拟启动健康检查；正式版会调用对应流程的恢复动作')});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='report-type'){state.reportType=el.dataset.type;state.reportPeriod=state.reportType==='week'?'09/22—09/28':'2026年9月';return render(true)}if(a==='generate-report')return generateReport();if(a==='report-detail')return reportDetail(reportArchive.find(x=>x.id===el.dataset.id));if(a==='experiment-status'){state.experimentStatus=el.dataset.status;return render(true)}if(a==='experiment-detail')return experimentDetail(el.dataset.id);if(a==='experiment-task'){state.taskFilter='all';state.taskOwner=el.dataset.owner;return goto('tasks')}if(a==='new-experiment')return newExperimentDrawer();if(a==='stop-activity')return stopActivityDrawer(el.dataset.id);if(a==='secret-detail')return secretDetail(el.dataset.word);if(a==='log-tab'){state.logTab=el.dataset.tab;return render(true)}});
document.addEventListener('submit',e=>{
  if(e.target.id==='stop-activity-form'){
    e.preventDefault();const form=new FormData(e.target),activity=incentiveActivities.find(x=>x.id===e.target.dataset.id),previous=activity.orders;
    Object.assign(activity,{orders:Number(form.get('orders')),phase:'ended',status:'人工停止',end:'09/23',requirement:`${activity.requirement} 停止原因：${safe(form.get('reason'))}；门槛比例 ${safe(form.get('ratio'))}%。`});
    activityOverrides[activity.id]={orders:activity.orders,phase:activity.phase,status:activity.status,end:activity.end,requirement:activity.requirement};storage.write('ops-activity-overrides-v1',activityOverrides);addOperation('停止激励活动',activity.name,`${previous} 单 → ${activity.orders} 单；${form.get('reason')}`);closeDrawer();state.activityView='ended';render();toast('活动已停止并转入历史结果');
  }
  if(e.target.id==='new-experiment-form'){
    e.preventDefault();const form=new FormData(e.target),row={id:`exp-${Date.now()}`,name:safe(form.get('name')),target:safe(form.get('target')),hypothesis:safe(form.get('hypothesis')),owner:safe(form.get('owner')),start:safe(form.get('start')),end:safe(form.get('end')),activity:'待关联',secret:safe(form.get('secret')),status:'进行中',task:form.get('createTask')?'已创建执行任务':'未创建任务',baseline:'待录入基准',goal:safe(form.get('goal')),result:'等待采集数据',conclusion:'测试进行中'};
    experimentRows.unshift(row);if(form.get('createTask'))tasks.push({name:`业务测试：${row.name}`,module:'业务测试',owner:row.owner,start:row.start,end:row.end,status:'未开始',alert:'正常',progress:null,note:row.target,report:'尚未提交进展。'});addOperation('新建业务测试',row.name,`负责人：${row.owner}；密令：${row.secret}`);closeDrawer();render();toast('测试已保存并关联任务');
  }
});
document.querySelector('#login').addEventListener('click',()=>toast('需要先配置飞书自建应用的 OAuth 授权信息'));
document.querySelector('#drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer()});
render();
